(ns clojure-algorithms.project-euler.problem-029.sol1
  "Euler Problem 29: count the distinct terms in the sequence generated by a^b
  for 2 <= a <= n and 2 <= b <= n.")

(defn solution
  "Returns the number of distinct values of a^b for 2 <= a,b <= n."
  ([] (solution 100))
  ([n]
   (count (into #{}
                (for [a (range 2 (inc n))
                      b (range 2 (inc n))]
                  (loop [i 0 acc 1N]
                    (if (= i b) acc (recur (inc i) (* acc a)))))))))
